import json

# Load all 5 days
days = {}
for d in range(36, 41):
    with open(f'scripts/iot_emb_day{d}.json', 'r', encoding='utf-8') as f:
        days[d] = json.load(f)

# Helper function to add paragraphs until part has >= 580 words
def ensure_part_words(day_num, part_idx, additional_paragraphs):
    part = days[day_num]['parts'][part_idx]
    words = sum(len(s.split()) for s in part['say'])
    for p in additional_paragraphs:
        if words >= 585:
            break
        part['say'].append(p)
        words = sum(len(s.split()) for s in part['say'])
    return words

